[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--navy:#0D1421;--gray:#808A9D;--gray-light:#EFF2F5;
  --bg:#FFFFFF;--bg-alt:#F8FAFC;--green:#16c784;--red:#ea3943;
  --text:#0D1421;--text-sec:#58667E;--border:#EFF2F5;
  --font:'Inter',system-ui,-apple-system,sans-serif;
}
html{font-size:14px;scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.5;-webkit-font-smoothing:antialiased}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
button{font-family:inherit;cursor:pointer}
.num{font-variant-numeric:tabular-nums}

/* NAV */
.nav{background:var(--navy);height:56px;display:flex;align-items:center;padding:0 24px;position:sticky;top:0;z-index:100}
.nav-brand{color:#fff;font-weight:700;font-size:16px;margin-right:32px;white-space:nowrap;display:flex;align-items:center;gap:8px}
.nav-brand svg{width:24px;height:24px}
.nav-links{display:flex;gap:4px;flex:1;overflow-x:auto}
.nav-links a{color:#9BA4B5;font-size:13px;font-weight:500;padding:6px 12px;border-radius:6px;white-space:nowrap;transition:color .15s,background .15s}
.nav-links a:hover,.nav-links a.active{color:#fff;background:rgba(255,255,255,.08);text-decoration:none}
.nav-right{display:flex;gap:8px;margin-left:16px}
.btn-login{color:#fff;font-size:13px;font-weight:500;padding:6px 16px;border-radius:6px;border:1px solid rgba(255,255,255,.2);background:transparent;transition:background .15s}
.btn-login:hover{background:rgba(255,255,255,.08)}
.btn-signup{color:#fff;font-size:13px;font-weight:600;padding:6px 16px;border-radius:6px;border:none;background:var(--blue);transition:background .15s}
.btn-signup:hover{background:#2b54e0}

/* TOP METRICS */
.metrics-bar{background:var(--bg-alt);border-bottom:1px solid var(--border);padding:10px 24px;display:flex;gap:32px;overflow-x:auto;font-size:13px}
.metric{display:flex;align-items:center;gap:6px;white-space:nowrap}
.metric-label{color:var(--text-sec);font-weight:500}
.metric-value{font-weight:600;color:var(--text)}
.metric-change{font-weight:500;font-size:12px}
.metric-change.up{color:var(--green)}
.metric-change.down{color:var(--red)}
.metric-badge{font-size:11px;font-weight:600;padding:2px 8px;border-radius:4px}
.metric-badge.neutral{background:#FEF3C7;color:#D97706}
.metric-badge.btc-season{background:#DBEAFE;color:#2563EB}

/* PROMO BANNER */
.promo-section{padding:12px 24px;border-bottom:1px solid var(--border)}
.promo-carousel{position:relative;overflow:hidden;border-radius:8px;background:linear-gradient(135deg,#1a1a2e 0%,#16213e 50%,#0f3460 100%);padding:16px 48px;min-height:52px;display:flex;align-items:center}
.promo-slide{color:#fff;font-size:13px;font-weight:500;display:none;align-items:center;gap:8px;width:100%}
.promo-slide.active{display:flex}
.promo-slide .promo-link{color:#60A5FA;font-weight:600;margin-left:4px;white-space:nowrap}
.promo-nav{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.12);border:none;color:#fff;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;transition:background .15s}
.promo-nav:hover{background:rgba(255,255,255,.2)}
.promo-nav.prev{left:8px}
.promo-nav.next{right:8px}
.promo-dots{position:absolute;bottom:6px;left:50%;transform:translateX(-50%);display:flex;gap:4px}
.promo-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);border:none;transition:background .15s}
.promo-dot.active{background:#fff}

/* AI ALERTS */
.ai-alerts{padding:12px 24px;border-bottom:1px solid var(--border);background:var(--bg)}
.ai-alerts-row{display:flex;align-items:center;gap:12px;margin-bottom:8px}
.ai-badge{background:linear-gradient(135deg,#6366F1,#8B5CF6);color:#fff;font-size:11px;font-weight:700;padding:3px 8px;border-radius:4px;white-space:nowrap}
.ai-prompt{font-size:13px;color:var(--text);font-weight:500}
.ai-suggestions{display:flex;gap:8px;overflow-x:auto;padding-bottom:4px}
.ai-suggestions button{font-size:12px;color:var(--text-sec);background:var(--bg-alt);border:1px solid var(--border);padding:5px 12px;border-radius:16px;white-space:nowrap;transition:all .15s}
.ai-suggestions button:hover{border-color:var(--blue);color:var(--blue);background:#EFF6FF}

/* NETWORK FILTER TABS */
.network-tabs{padding:12px 24px 0;border-bottom:1px solid var(--border);display:flex;gap:4px;overflow-x:auto;background:var(--bg)}
.network-tab{font-size:13px;font-weight:500;color:var(--text-sec);padding:8px 16px;border:none;background:none;border-bottom:2px solid transparent;transition:all .15s;white-space:nowrap}
.network-tab:hover{color:var(--text)}
.network-tab.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:600}

/* CATEGORY TABS + CONTROLS */
.controls-row{padding:12px 24px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;border-bottom:1px solid var(--border)}
.cat-tabs{display:flex;gap:4px;overflow-x:auto;flex:1}
.cat-tab{font-size:13px;font-weight:500;color:var(--text-sec);padding:6px 14px;border-radius:6px;border:1px solid var(--border);background:var(--bg);transition:all .15s;white-space:nowrap}
.cat-tab:hover{border-color:var(--blue);color:var(--blue)}
.cat-tab.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.table-controls{display:flex;gap:6px;align-items:center}
.ctrl-btn{font-size:12px;font-weight:500;color:var(--text-sec);padding:6px 12px;border-radius:6px;border:1px solid var(--border);background:var(--bg);display:flex;align-items:center;gap:4px;transition:all .15s;white-space:nowrap}
.ctrl-btn:hover{border-color:var(--blue);color:var(--blue)}
.ctrl-btn svg{width:14px;height:14px}
.ctrl-dropdown{position:relative}
.ctrl-dropdown-menu{display:none;position:absolute;top:100%;right:0;margin-top:4px;background:#fff;border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.1);z-index:50;min-width:200px;padding:8px}
.ctrl-dropdown-menu.open{display:block}
.ctrl-dropdown-menu label{display:flex;align-items:center;gap:8px;padding:6px 8px;font-size:12px;color:var(--text);cursor:pointer;border-radius:4px;transition:background .1s}
.ctrl-dropdown-menu label:hover{background:var(--bg-alt)}
.ctrl-dropdown-menu input[type="checkbox"]{accent-color:var(--blue)}

/* FILTER PANEL */
.filter-panel{display:none;padding:16px 24px;border-bottom:1px solid var(--border);background:var(--bg-alt);gap:16px;flex-wrap:wrap}
.filter-panel.open{display:flex}
.filter-group{display:flex;flex-direction:column;gap:6px}
.filter-group label{font-size:11px;font-weight:600;color:var(--text-sec);text-transform:uppercase;letter-spacing:.04em}
.filter-group select,.filter-group input{font-size:13px;padding:6px 10px;border:1px solid var(--border);border-radius:6px;background:#fff;font-family:inherit}
.filter-actions{display:flex;align-items:flex-end;gap:8px}
.filter-actions button{font-size:12px;font-weight:500;padding:6px 14px;border-radius:6px;border:1px solid var(--border)}
.filter-actions .apply{background:var(--blue);color:#fff;border-color:var(--blue)}
.filter-actions .reset{background:#fff;color:var(--text-sec)}

/* INDEX TRACKER */
.index-row{background:var(--bg-alt);border-bottom:1px solid var(--border);padding:8px 24px;display:flex;align-items:center;gap:12px;font-size:13px}
.index-label{font-weight:600;color:var(--text);white-space:nowrap}
.index-price{font-weight:600}
.index-change{font-weight:500;font-size:12px}
.index-change.up{color:var(--green)}
.index-change.down{color:var(--red)}

/* TABLE */
.table-wrap{overflow-x:auto;background:var(--bg)}
table{width:100%;border-collapse:collapse;min-width:1100px}
thead{background:var(--bg-alt)}
th{font-size:11px;font-weight:600;color:var(--text-sec);text-transform:uppercase;letter-spacing:.04em;padding:10px 12px;text-align:left;border-bottom:1px solid var(--border);white-space:nowrap;cursor:pointer;user-select:none;transition:color .15s}
th:hover{color:var(--text)}
th.right,td.right{text-align:right}
th .sort-icon{display:inline-block;margin-left:2px;opacity:.4;font-size:10px}
th.sorted .sort-icon{opacity:1;color:var(--blue)}
td{padding:10px 12px;border-bottom:1px solid var(--border);font-size:13px;vertical-align:middle}
tr:hover{background:#F8FAFC}
tr.index-separator{border-bottom:2px solid var(--border)}

.coin-cell{display:flex;align-items:center;gap:8px;min-width:160px}
.coin-rank{color:var(--text-sec);font-weight:500;font-size:12px;width:20px;text-align:center}
.coin-icon{width:24px;height:24px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:10px;color:#fff}
.coin-name{font-weight:600;color:var(--text)}
.coin-symbol{color:var(--text-sec);font-size:12px;margin-left:4px}
.price{font-weight:600}
.change{font-weight:500;font-size:12px}
.change.up{color:var(--green)}
.change.down{color:var(--red)}
.supply-cell{font-size:12px}
.supply-val{color:var(--text)}
.supply-unit{color:var(--text-sec);margin-left:2px}
.sparkline-cell{width:120px;height:32px}
.sparkline-cell svg{width:100%;height:100%}

/* PAGINATION */
.pagination{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-top:1px solid var(--border);font-size:13px;color:var(--text-sec)}
.page-info{white-space:nowrap}
.page-buttons{display:flex;gap:4px;flex-wrap:wrap}
.page-btn{width:32px;height:32px;display:flex;align-items:center;justify-content:center;border:1px solid var(--border);border-radius:6px;font-size:13px;font-weight:500;color:var(--text-sec);background:var(--bg);transition:all .15s}
.page-btn:hover{border-color:var(--blue);color:var(--blue)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.page-ellipsis{width:32px;height:32px;display:flex;align-items:center;justify-content:center;color:var(--text-sec)}

/* MARKET SUMMARY */
.market-summary{padding:24px;border-bottom:1px solid var(--border);max-width:800px}
.market-summary p{font-size:14px;line-height:1.7;color:var(--text)}
.market-summary strong{font-weight:600}
.market-summary .read-more-btn{color:var(--blue);font-weight:500;font-size:13px;background:none;border:none;padding:4px 0;cursor:pointer}
.market-summary .read-more-btn:hover{text-decoration:underline}
.summary-expanded{display:none;margin-top:12px;padding-top:12px;border-top:1px solid var(--border)}
.summary-expanded.show{display:block}
.summary-expanded p{font-size:13px;line-height:1.6;color:var(--text-sec)}

/* INFO CONTENT */
.info-content{padding:24px;max-width:800px;border-bottom:1px solid var(--border)}
.info-content h2{font-size:20px;font-weight:700;margin-bottom:12px;color:var(--text)}
.info-content h3{font-size:16px;font-weight:600;margin:20px 0 8px;color:var(--text)}
.info-content p{font-size:14px;line-height:1.7;color:var(--text-sec)}

/* FOOTER */
.footer{background:var(--navy);color:#9BA4B5;padding:40px 24px 24px}
.footer-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:32px;max-width:1200px;margin:0 auto 32px}
.footer-col h4{color:#fff;font-size:13px;font-weight:600;margin-bottom:12px;text-transform:uppercase;letter-spacing:.04em}
.footer-col a{display:block;font-size:13px;color:#9BA4B5;padding:3px 0;transition:color .15s}
.footer-col a:hover{color:#fff;text-decoration:none}
.footer-bottom{border-top:1px solid rgba(255,255,255,.08);padding-top:16px;text-align:center;font-size:12px;color:#58667E}

/* SCROLLBAR */
::-webkit-scrollbar{height:6px;width:6px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:#CBD5E1;border-radius:3px}
::-webkit-scrollbar-thumb:hover{background:#94A3B8}

/* RESPONSIVE */
@media(max-width:768px){
  .metrics-bar{gap:16px;padding:8px 12px;font-size:12px}
  .promo-section,.ai-alerts{padding:8px 12px}
  .network-tabs,.controls-row{padding:8px 12px}
  .cat-tab{padding:5px 10px;font-size:12px}
  .table-wrap{padding:0}
  td,th{padding:8px 6px;font-size:12px}
  .coin-cell{min-width:120px}
  .market-summary,.info-content{padding:16px 12px}
}
</style>
</head>
