// ========== HELPERS ==========
function fmt(n){
  if(n>=1e12)return'$'+(n/1e12).toFixed(2)+'T';
  if(n>=1e9)return'$'+(n/1e9).toFixed(2)+'B';
  if(n>=1e6)return'$'+(n/1e6).toFixed(2)+'M';
  return'$'+n.toLocaleString('en-US');
}
function fmtSupply(n){
  if(n>=1e12)return(n/1e12).toFixed(2)+'T';
  if(n>=1e9)return(n/1e9).toFixed(2)+'B';
  if(n>=1e6)return(n/1e6).toFixed(2)+'M';
  return n.toLocaleString('en-US');
}
function fmtPrice(p){
  if(p>=1000)return'$'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(p>=1)return'$'+p.toFixed(2);
  if(p>=.01)return'$'+p.toFixed(4);
  return'$'+p.toFixed(8);
}
function fmtPct(v){
  const s=v>=0?'+':'';
  return s+v.toFixed(2)+'%';
}
function sparklineSVG(data,w=120,h=32){
  const mn=Math.min(...data),mx=Math.max(...data),range=mx-mn||1;
  const pts=data.map((v,i)=>{
    const x=(i/(data.length-1))*w;
    const y=h-((v-mn)/range)*h;
    return`${x},${y}`;
  }).join(' ');
  const last=data[data.length-1];
  const isUp=data[data.length-1]>=data[0];
  const color=isUp?'#16c784':'#ea3943';
  return`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}
function coinColor(s){
  const colors={BTC:'#F7931A',ETH:'#627EEA',USDT:'#26A17B',XRP:'#23292F',BNB:'#F3BA2F',SOL:'#9945FF',USDC:'#2775CA',ADA:'#0033AD',DOGE:'#C2A633',TRX:'#FF0013',LINK:'#2A5ADA',AVAX:'#E84142',DOT:'#E6007A',SHIB:'#FFA409',MATIC:'#8247E5',LTC:'#BFBBBB',UNI:'#FF007A',BCH:'#8DC351',ATOM:'#2E3148',XLM:'#14B6E7'};
  return colors[s]||'#3861FB';
}

// ========== RENDER TABLE ==========
let sortCol='r',sortDir=1;
const colVisibility={1h:true,'24h':true,'7d':true,mcap:true,vol:true,supply:true,spark:true};

function renderTable(data){
  const tb=document.getElementById('cryptoBody');
  tb.innerHTML='';
  data.forEach(c=>{
    const tr=document.createElement('tr');
    const ch1=c.c1h>=0?'up':'down';
    const ch24=c.c24h>=0?'up':'down';
    const ch7=c.c7d>=0?'up':'down';
    let h=`<td class="num">${c.r}</td>`;
    h+=`<td><div class="coin-cell"><span class="coin-icon" style="background:${coinColor(c.s)}">${c.s.slice(0,2)}</span><span class="coin-name">${c.n}</span><span class="coin-symbol">${c.s}</span></div></td>`;
    h+=`<td class="right num price">${fmtPrice(c.p)}</td>`;
    if(colVisibility['1h'])h+=`<td class="right num change ${ch1}">${fmtPct(c.c1h)}</td>`;
    if(colVisibility['24h'])h+=`<td class="right num change ${ch24}">${fmtPct(c.c24h)}</td>`;
    if(colVisibility['7d'])h+=`<td class="right num change ${ch7}">${fmtPct(c.c7d)}</td>`;
    if(colVisibility.mcap)h+=`<td class="right num">${fmt(c.mc)}</td>`;
    if(colVisibility.vol)h+=`<td class="right num">${fmt(c.v)}</td>`;
    if(colVisibility.supply)h+=`<td class="right num supply-cell"><span class="supply-val">${fmtSupply(c.sup)}</span><span class="supply-unit"> ${c.su}</span></td>`;
    if(colVisibility.spark)h+=`<td class="sparkline-cell">${sparklineSVG(c.sp)}</td>`;
    tr.innerHTML=h;
    tb.appendChild(tr);
  });
}

function sortData(col){
  if(sortCol===col)sortDir*=-1;else{sortCol=col;sortDir=1;}
  const keyMap={name:'n',price:'p',mcap:'mc',vol:'v',r:'r'};
  const key=keyMap[col]||col;
  const sorted=[...CRYPTO_DATA].sort((a,b)=>{
    const va=a[key],vb=b[key];
    if(typeof va==='string')return va.localeCompare(vb)*sortDir;
    return(va-vb)*sortDir;
  });
  renderTable(sorted);
}

// ========== INTERACTIONS ==========

// Promo carousel
let promoIdx=0;
const promoSlides=document.querySelectorAll('.promo-slide');
const dotsC=document.getElementById('promoDots');
promoSlides.forEach((_,i)=>{const d=document.createElement('button');d.className='promo-dot'+(i===0?' active':'');d.onclick=()=>goPromo(i);dotsC.appendChild(d);});
function goPromo(i){promoIdx=i;promoSlides.forEach((s,j)=>{s.classList.toggle('active',j===i);});dotsC.querySelectorAll('.promo-dot').forEach((d,j)=>{d.classList.toggle('active',j===i);});}
function rotatePromo(dir){goPromo((promoIdx+dir+promoSlides.length)%promoSlides.length);}
setInterval(()=>rotatePromo(1),5000);

// Network tabs
document.getElementById('networkTabs').addEventListener('click',e=>{
  if(!e.target.classList.contains('network-tab'))return;
  document.querySelectorAll('.network-tab').forEach(t=>t.classList.remove('active'));
  e.target.classList.add('active');
  const net=e.target.dataset.network;
  const filtered=net==='all'?CRYPTO_DATA:CRYPTO_DATA.filter(c=>c.net===net);
  renderTable(filtered);
});

// Category tabs
document.getElementById('catTabs').addEventListener('click',e=>{
  if(!e.target.classList.contains('cat-tab'))return;
  document.querySelectorAll('.cat-tab').forEach(t=>t.classList.remove('active'));
  e.target.classList.add('active');
  // Simulate category filtering
  const cat=e.target.dataset.cat;
  if(cat==='watchlist'){
    renderTable(CRYPTO_DATA.slice(0,10));
  }else if(cat==='trending'){
    const trending=[...CRYPTO_DATA].sort((a,b)=>Math.abs(b.c24h)-Math.abs(a.c24h)).slice(0,20);
    renderTable(trending);
  }else if(cat==='new'){
    renderTable(CRYPTO_DATA.slice(80));
  }else{
    renderTable(CRYPTO_DATA);
  }
});

// Table sorting
document.querySelector('thead').addEventListener('click',e=>{
  const th=e.target.closest('th');
  if(!th||!th.dataset.sort)return;
  document.querySelectorAll('th').forEach(t=>t.classList.remove('sorted'));
  th.classList.add('sorted');
  sortData(th.dataset.sort);
});

// Columns toggle
function toggleColumnsMenu(){document.getElementById('columnsMenu').classList.toggle('open');}
document.getElementById('columnsMenu').addEventListener('change',e=>{
  const col=e.target.dataset.col;
  colVisibility[col]=e.target.checked;
  // Toggle column visibility in table
  document.querySelectorAll(`[data-col="${col}"]`).forEach(el=>{
    if(el.tagName==='TH')el.style.display=colVisibility[col]?'':'none';
  });
  renderTable(CRYPTO_DATA);
});
document.addEventListener('click',e=>{
  if(!e.target.closest('.ctrl-dropdown'))document.getElementById('columnsMenu').classList.remove('open');
});

// Filters toggle
function toggleFilters(){document.getElementById('filterPanel').classList.toggle('open');}

// Market summary accordion
function toggleSummary(btn){
  const exp=document.getElementById('summaryExpanded');
  const show=exp.classList.toggle('show');
  btn.textContent=show?'Show Less':'Read More';
}

// Pagination
document.querySelectorAll('.page-btn').forEach(btn=>{
  btn.addEventListener('click',()=>{
    document.querySelectorAll('.page-btn').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
  });
});

// ========== INIT ==========
renderTable(CRYPTO_DATA);
</script>
